import{showToast as o}from"./utils.js";const i=document.querySelector("form");i&&i.addEventListener("submit",async s=>{s.preventDefault();const r=s.target,e=r.querySelector('button[type="submit"]'),c=e.innerHTML;e.disabled=!0,e.innerHTML='<i class="fas fa-spinner fa-spin"></i> Sending...';try{const t=new FormData(r),l=Object.fromEntries(t.entries()),n=await fetch(r.action,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify(l)});if(n.ok)o("Message sent successfully! We will get back to you soon.","success"),r.reset();else{const a=await n.json();a.errors?o(a.errors.map(m=>m.message).join(", "),"error"):o("Oops! There was a problem submitting your form.","error")}}catch(t){console.error("Form submission error:",t),o("Network error. Please check your connection and try again.","error")}finally{e.disabled=!1,e.innerHTML=c}});
